#include <iostream>
#include <iomanip>
#include <string_view>
#include <array>

constexpr size_t SUITS = 4;
constexpr size_t FACES = 13;

constexpr std::array<std::string_view, SUITS> suitNames = {
    "Hearts", "Diamonds", "Clubs", "Spades"
};

constexpr std::array<std::string_view, FACES> faceNames = {
    "Ace", "Deuce", "Three", "Four",
    "Five", "Six", "Seven", "Eight",
    "Nine", "Ten", "Jack", "Queen", "King"
};

struct Card {
    size_t suit;
    size_t face;
};

int main() {
    // Representative sequence matching the first 4 cards of Fig. 7.25
    const std::array<Card, 4> dealt = {{
        { 0, 8 },  // Nine of Hearts
        { 2, 4 },  // Five of Clubs
        { 3, 11 }, // Queen of Spades
        { 3, 2 }   // Three of Spades
    }};

    for (size_t card = 1; card <= dealt.size(); ++card) {
        const auto& c = dealt[card - 1];
        // %5s: right-justified width 5
        // %-8s: left-justified width 8
        std::cout << std::right << std::setw(5) << faceNames[c.face]
                  << " of "
                  << std::left << std::setw(8) << suitNames[c.suit]
                  << ((card % 2 == 0) ? "\n" : "\t");
    }

    return 0;
}

#include <iostream>
#include <cstddef>

// Ascending comparator: returns true if elements are out of order (b < a)
int ascending(int a, int b) {
    return b < a;
}

// Descending comparator: returns true if elements are out of order (b > a)
int descending(int a, int b) {
    return b > a;
}

void swap(int *element1Ptr, int *element2Ptr) {
    int hold = *element1Ptr;
    *element1Ptr = *element2Ptr;
    *element2Ptr = hold;
}

// Multipurpose bubble sort accepting a comparator function pointer
void bubble(int work[], size_t size, int (*compare)(int, int)) {
    for (size_t pass = 1; pass < size; ++pass) {
        for (size_t count = 0; count < size - 1; ++count) {
            // Explicit dereference syntax (*compare)(...)
            if ((*compare)(work[count], work[count + 1])) {
                swap(&work[count], &work[count + 1]);
            }
        }
    }
}

void printArray(const int arr[], size_t size) {
    for (size_t i = 0; i < size; ++i) {
        std::cout << arr[i] << (i + 1 == size ? "" : " ");
    }
    std::cout << "\n";
}

int main() {
    int a1[10] = { 2, 6, 4, 8, 10, 12, 89, 68, 45, 37 };
    int a2[10] = { 2, 6, 4, 8, 10, 12, 89, 68, 45, 37 };
    constexpr size_t SIZE = 10;

    std::cout << "Original:\n";
    printArray(a1, SIZE);

    bubble(a1, SIZE, ascending);
    std::cout << "Ascending:\n";
    printArray(a1, SIZE);

    bubble(a2, SIZE, descending);
    std::cout << "Descending:\n";
    printArray(a2, SIZE);

    return 0;
}
